function spawn(x,y,type='wolf',level=1,boss=false){if(blocked(x,y,S.player?.zone||'coast')){let found=false;for(let radius=1;radius<=7&&!found;radius++)for(const [dx,dy] of [[radius,0],[-radius,0],[0,radius],[0,-radius],[radius,radius],[-radius,-radius]])if(!blocked(x+dx,y+dy,S.player?.zone||'coast')){x+=dx;y+=dy;found=true;break;}}const test=S.player?.testMode,st=test?stats(S.player):null,budget=enemyBudget(level,boss);const maxHp=budget.hp,theme=MOB_THEMES[S.player?.region||0];const e={id:Math.random().toString(36),x,y,homeX:x,homeY:y,type,level,boss,name:boss?'Guardião de '+(CONTENT?.regions[S.player?.region||0]?.name||'Lúmen'):type==='wisp'?theme.spirit:theme.name,archetype:boss?'construct':type==='wisp'?'spirit':theme.kind,theme:S.player?.region||0,hp:maxHp,maxHp,def:budget.defense,atk:budget.attack,speed:boss?1.8:2.05,stun:0,cooldown:1+Math.random(),winding:0,deadTimer:0,respawn:0,moving:false};if(boss)e.shield=maxHp*.10;S.enemies.push(e);return e;}
