function nextWave(){const waveLevel=S.dgData?.level_min||3;S.dungeonWave++;if(S.dungeonWave<=2){announce('ONDA '+S.dungeonWave+' / 3');for(let i=0;i<3;i++)spawn(15+i*3,16+Math.random()*3,S.dungeonWave===2?'wisp':'wolf',waveLevel);}else if(S.dungeonWave===3){const guardian=spawn(22,18,'guardian',waveLevel,true);guardian.name=S.dgData?.boss||'Sentinela do Farol';announce('O GUARDIÃO DESPERTOU');}else{S.dungeonWon=true;const p=S.player;p.dungeonClears++;const reward=dungeonReward(p,S.dgData);p.shards+=S.dgData?.players===5?3:1;gainXP(reward.xp);const drop=campaignDrop(p,S.dgData?.equipment_level||p.level);if(p.bag.length<80)p.bag.push(drop);announce('MASMORRA CONCLUÍDA');toast('+'+reward.gold+' ouro · +'+reward.xp+'XP · '+drop.name);p.regionClears[p.region||0]=(p.regionClears[p.region||0]||0)+1;addMaterials(p,{'Pluma Astral':2+(S.dgData?.players||1),'Essência de Aura':3+(S.dgData?.players||1)});if(p.quest===3)p.quest=4;save();}}
function start(p){initAscension(p);S.dgData=null;S.bossEncounter=null;p.attributes||={for:0,int:0,des:0};p.materials||={};if(!p.progressionVersion){p.gold=Math.max(p.gold,5000);p.shards=Math.max(p.shards,10);addMaterials(p,{L01:40,E01:10,N01:2,K01:10,P01:10});p.progressionVersion=4;}p.bar||=[0,1,2,3];p.passive||=PASSIVE_OPTIONS[p.classId][0][2];p.region||=0;p.energy??=100;p.resource??=0;S.skillCD={};S.timers={};S.shield=0;S.guard=false;S.player=p;for(const slot of ['head','hands','legs','boots'])if(!(slot in p.equipped)){const piece=item(p.classId,1,slot);p.bag.push(piece);p.equipped[slot]=piece.id;}const st=stats(p);p.hp=clamp(p.hp||st.hp,1,st.hp);p.mp=clamp(p.mp??st.mp,0,st.mp);if(p.zone==='dungeon'){p.zone='coast';p.x=27;p.y=11;}S.cd={s1:0,s2:0,def:0,hp:0,mp:0,basic:0};S.buffShield=0;S.eye=0;S.pulses=[];populate();mode='game';document.body.dataset.playing='true';document.body.dataset.class=p.classId;$('welcome').hidden=true;$('creation').hidden=true;$('hud').hidden=false;$('heroName').textContent=p.name;$('avatar').textContent=CLASSES[p.classId].icon;const c=CLASSES[p.classId];$('attack').querySelector('span').textContent=c.icon;for(const [id,key] of [['skill1','skill1'],['skill2','skill2'],['defense','defense']]){$(id).querySelector('small').textContent=c[key].name;$(id).querySelector('span').textContent=c[key].icon||'⛨';$(id).setAttribute('aria-label',c[key].name);}S.nav=false;updateSkillLabels();r.cam={x:p.x,y:p.y};save();updateHUD();toast(p.testMode?'Laboratório250. Para ganhar níveis, escolha Campanha na tela inicial.':'Toque na missão para ir ao objetivo. Itens e Evoluir ficam na barra inferior.');}
