function showModal(title,sub,html){portraitPreview=null;if(!html||!String(html).trim())return;$('modalTitle').textContent=title;$('modalSub').textContent=sub;$('modalBody').innerHTML=html;$('modalBody').scrollTop=0;$('modal').querySelector('.modal').dataset.panel=html.includes('inventoryLayout')?'inventory':html.includes('itemSheet')?'item':html.includes('ascensionLayout')?'ascension':'standard';$('modal').hidden=false;S.attack=false;keys.clear();joy.x=joy.y=0;S.nav=false;S.goal=null;$('stick').style.transform='';}
