function gainXP(amount){const p=S.player,levels=advanceXP(p,amount);if(levels){const st=stats(p);p.hp=st.hp;p.mp=st.mp;ring(p.x,p.y,'#e9d49a');fx('ascend',p.x,p.y,{life:1.5,color:'#ffe7a3'});announce('NÍVEL '+p.level+' · +'+(levels*5)+' ATRIBUTOS');p.gold+=levels*500;p.shards+=levels;S.levelPulse=1.5;tone(880,.4);save();}return levels;}
function kill(e){if(e.training){e.hp=e.maxHp;e.poison=null;e.stun=0;return;}e.hp=0;e.deadTimer=1.8;e.respawn=22;const p=S.player;p.killCount++;if(p.killCount%3===0)addMaterials(p,{'Pluma Astral':1});if(p.killCount%2===0)addMaterials(p,{'Essência de Aura':1});if(e.boss)addMaterials(p,{'Pluma Astral':3,'Essência de Aura':4});if(e.bossMeta){p.bossTimers||={};p.bossTimers[e.bossMeta.id]=Date.now()+(e.bossMeta.respawn_seconds_after_death||3600)*1000;S.dungeonWon=true;if(e.bossMeta.division==='CATACLYSM'){addMaterials(p,{'Núcleo de Cataclismo':2,'Fragmento de Extensor':1});if(e.bossMeta.id==='CAT-05'){addMaterials(p,{'Fragmento da Origem':1});if(p.materials['Fragmento da Origem']>=8){p.materials['Fragmento da Origem']-=8;addMaterials(p,{'Selo_da_Origem':1});}}if(Math.random()<.01)addMaterials(p,{'Extensor Astral':1});if(p.materials['Fragmento de Extensor']>=30){p.materials['Fragmento de Extensor']-=30;addMaterials(p,{'Extensor Astral':1});}}if(p.bag.length<80)p.bag.push(campaignDrop(p,e.level));announce('CHEFE DERROTADO · MATERIAIS RECEBIDOS');}p.huntCount=(p.huntCount||0)+1;if(p.huntCount%5===0){gainXP(Math.ceil(xpBase(p.level)*.3));p.gold+=200;toast('Contrato de caça concluído: EXP extra e200ouro. Novo contrato disponível.');}const reward=mobReward(p,e.level,e.boss);gainXP(reward.xp);p.shards+=e.boss?2:Math.random()<.35?1:0;floating(e.x,e.y,'+'+reward.gold+' ◈ · +'+reward.xp+'XP','#e9cf8b');if(e.type==='wolf'&&p.quest===1){p.kills++;if(p.kills>=5){p.kills=5;p.quest=2;announce('OBJETIVO CONCLUÍDO');toast('Volte até Ilyra para receber a recompensa.');}}
if(Math.random()<.32&&!e.boss){p.shards++;toast('Cristal de aprimoramento coletado.');}if(Math.random()<.16&&!e.boss){if(p.bag.length<80){const drop=campaignDrop(p,e.level);p.bag.push(drop);toast('Novo equipamento: '+drop.name);}else toast('Mochila cheia. Venda um equipamento na mochila.');}if(Math.random()<.20)p.pots.hp++;S.loot.push({x:e.x,y:e.y,life:2});if(S.target===e)S.target=null;save();}
function hitEnemy(e,coef=1,stun=0,sourceIndex=null){if(!e||e.hp<=0)return;const p=S.player,st=stats(p),skillIndex=sourceIndex??S.castingIndex,isSkill=skillIndex!=null,now=S.time,cls=p.classId,profile=attackProfile(st,cls,skillIndex);let bonus=1;if(p.passive==='hunter')bonus*=1.08;if(p.passive==='colossus'&&e.boss)bonus*=1.08;if(cls==='VIG'&&!isSkill){if(S.cadenceTarget===e.id&&now-(S.lastBasic||0)<3)S.cadence=Math.min(5,(S.cadence||0)+1);else S.cadence=0;S.cadenceTarget=e.id;S.lastBasic=now;bonus*=1+.03*(S.cadence||0);if(Math.hypot(e.x-p.x,e.y-p.y)>8)bonus*=1.08;if((S.timers.horizon||0)>0)bonus*=1.25;}
if(cls==='DUE'&&isSkill)bonus*=1+.03*p.resource;if(isSkill)bonus*=1+effectiveAmp(profile.amp,st,e)+((S.timers.amp||0)>0?(S.ampAmount||.15):0);if(p.passive==='duelist'&&cls==='ARC'&&S.castingIndex===0)bonus*=1.08;if(p.passive==='swordsman'&&S.castingIndex===0)bonus*=1.06;if(p.passive==='conductor'&&S.castingIndex===1)bonus*=1.04;if(S.retaliate&&!isSkill){coef+=.3;S.retaliate=false;}if(S.resonant&&!isSkill){coef+=.3;S.resonant=false;}
if(cls==='ESP'&&isSkill&&e.facing){const dot=(p.x-e.x)*e.facing.x+(p.y-e.y)*e.facing.y;if(dot<0)bonus*=1.08;}
const defense=Math.max(0,e.def*(e.exposed>0?1-(e.reduction||.1):1)-profile.pen*(p.passive==='pen'||cls==='RUP'?1.1:1));const accuracy=clamp(.85+(st.acc-e.level*10)/10000+(p.passive==='accurate'?.05:0)+(e.mark>0?.10:0),.65,.99);if(Math.random()>accuracy){floating(e.x,e.y,'ERROU','#bfcbd3');return;}const out=damage(profile.atk,coef*bonus,defense,criticalChance(st,e,(S.eye>0?.12:0)+((S.timers.night||0)>0?.15:0)),criticalMultiplier(st,e));let remaining=out.value;if(e.shield>0){const shieldDamage=remaining*(p.passive==='demolisher'?1.15:1),absorbed=Math.min(e.shield,shieldDamage);e.shield-=absorbed;remaining=Math.max(0,remaining-absorbed/(p.passive==='demolisher'?1.15:1));}e.hp-=remaining;e.flash=.16;for(let n=0;n<5;n++)fx('spark',e.x,e.y,{angle:n*1.256,color:CLASSES[cls].color,life:.40});e.stun=Math.max(e.stun,stun);if(stun>0)e.winding=0;S.lastCombat=S.time;S.attackAnim=.38;S.facing={x:e.x-p.x,y:e.y-p.y};if(CLASSES[cls].range<5)fx('slash',p.x,p.y,{life:.38,color:CLASSES[cls].color,tx:e.x,ty:e.y});floating(e.x,e.y,(out.critical?'CRÍTICO ':'')+out.value,out.critical?'#ffe3a4':'#fff2d7',out.critical);if(!isSkill&&cls==='ESP'){S.basicHits=(S.basicHits||0)+1;if(S.basicHits%2===0)p.resource=Math.min(5,p.resource+1);}if(cls==='RUP')p.resource=Math.min(100,p.resource+(isSkill?12:8));tone(out.critical?780:440,.05,'triangle',.02);if(e.hp<=0)kill(e);}

function chooseTarget(){const p=S.player;if(S.target?.hp>0&&Math.hypot(S.target.x-p.x,S.target.y-p.y)<16)return S.target;S.target=S.enemies.filter(e=>e.hp>0).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0]||null;return S.target;}
function dashFromTarget(distance){const p=S.player,e=chooseTarget();const dx=e?p.x-e.x:1,dy=e?p.y-e.y:1,len=Math.hypot(dx,dy)||1;for(let k=0;k<15;k++){const x=p.x+dx/len*distance/15,y=p.y+dy/len*distance/15;if(!blocked(x,y,p.zone)){p.x=x;p.y=y;}}S.goal=null;S.nav=false;}
function useSkill(which){const index=which==='def'?5:which==='ult'?6:S.player.bar[Number(which.slice(1))-1];castSkill(index);}
function castSkill(index){if(mode!=='game'||!$('modal').hidden)return;const p=S.player,c=CLASSES[p.classId],st=stats(p),skill=KITS[p.classId][index],level=[1,10,25,45,70,8,130][index];S.skillCD||={};S.timers||={};if(!p.testMode&&p.level<level){toast('Habilidade liberada no nível'+level+'. Ative o laboratório para testar todas.');return;}if((S.skillCD[index]||0)>0){toast('Recarga: '+Math.ceil(S.skillCD[index])+'s.');return;}if(index===6&&p.energy<100){toast('Suprema exige100energia.');return;}const cost=skill.cost*(p.passive==='veteran'?.9:1);if(p.mp<cost){toast('Mana insuficiente.');return;}
const targeted=['shot','spell','strike','double','dash','expose','execute','dispel','slow','finale','rune','mark','taunt'].includes(skill.kind);let e=targeted?chooseTarget():null;if(targeted&&(!e||Math.hypot(e.x-p.x,e.y-p.y)>skill.range)){toast('Selecione um alvo no alcance ('+skill.range+'m).');return;}if(skill.kind==='fury'&&p.resource<60){toast('Precisa de60Fúria. Ataque para acumular.');return;}
if(skill.kind==='intercept'){toast('Interceptar exige um aliado. O teste de cooperação depende da próxima etapa multiplayer.');return;}
fx('sigil',p.x,p.y,{color:c.color,life:index===6?1.2:.65,ultimate:index===6});p.mp-=cost;if(index===6)p.energy=0;S.skillCDMax||={};S.skillCDMax[index]=Math.max(.2,(skill.cd-(index===5&&p.passive==='survivor'?10:0))*(1-st.cdr));S.skillCD[index]=S.skillCDMax[index];S.goal=null;S.nav=false;const perform=()=>executeSkill(skill,index,e);if(skill.cast){S.cast={left:skill.cast,perform,name:skill.name};S.attack=false;toast('Conjurando '+skill.name+'…');}else perform();updateSkillLabels();}
function executeSkill(skill,index,e){const p=S.player,c=CLASSES[p.classId],st=stats(p),kind=skill.kind;S.castingIndex=index;S.lastCombat=S.time;S.attackAnim=.65;fx('channel',p.x,p.y,{color:c.color,life:.8,ultimate:index===6});if(e&&skill.coef)fx('impact',e.x,e.y,{color:c.color,life:.65});if(kind==='storm')fx('storm',p.x,p.y,{color:c.color,life:2});S.timers||={};const doHit=(en,coef)=>{if(en?.hp>0)hitEnemy(en,coef,en.boss?Math.min(.35,skill.stun||0):skill.stun||0)};
if(kind==='dash'&&e){fx('dashtrail',p.x,p.y,{tx:e.x,ty:e.y,color:c.color,life:.6});const d=Math.hypot(e.x-p.x,e.y-p.y)||1,x=e.x-(e.x-p.x)/d*1.4,y=e.y-(e.y-p.y)/d*1.4;if(!blocked(x,y,p.zone)){p.x=x;p.y=y;}if(skill.coef)doHit(e,skill.coef);}
if(['backstep','blink','break'].includes(kind)){if(kind!=='break')dashFromTarget((kind==='blink'?4:3)+(p.passive==='predator'?1:0));S.timers.controlImmune=1;if(p.passive==='barrier'){S.shield=st.hp*.08;S.timers.barrier=5;}}
if(['shot','spell','strike','double','expose','execute','dispel','slow','finale','rune','eclipse'].includes(kind)){
let coef=skill.coef;if(kind==='execute'){const seals=p.resource;coef+=.35*seals;if(seals===5&&!(S.timers.blood||0)){p.mp=Math.min(st.mp,p.mp+5);S.timers.blood=12;}p.resource=0;if(p.passive==='poison')e.poison={ticks:3,timer:1,coef:.1,sourceIndex:index};}if(kind==='finale'){const consumed=p.resource;coef+=.25*consumed;p.resource=(S.timers.dance||0)>0?Math.max(0,p.resource-2):0;if(p.passive==='resonant')S.resonant=true;if(p.passive==='tireless'&&consumed>=5)S.skillCD[1]=Math.max(0,(S.skillCD[1]||0)-1);}if(kind==='rune'||kind==='eclipse'){coef+=kind==='rune'?.25*p.resource:coef*.2*p.resource;if(p.resource>=3&&p.passive==='balance'){S.shield=st.hp*.04;S.timers.barrier=5;}p.resource=0;}
if(kind==='eclipse'){for(const en of S.enemies.filter(v=>v.hp>0&&Math.hypot(v.x-p.x,v.y-p.y)<skill.range))doHit(en,coef);fx('nova',p.x,p.y,{color:c.color,life:.8});}else doHit(e,coef);
if(kind==='double'&&p.classId==='ESP')p.resource=Math.min(5,p.resource+2);if(kind==='expose'&&e){e.exposed=5;e.reduction=skill.reduction;}if(kind==='slow'&&e)e.slow=2;if(['shot','spell','dispel','rune'].includes(kind)&&e)fx(kind==='shot'?'arrow':'bolt',p.x,p.y,{sx:p.x,sy:p.y,tx:e.x,ty:e.y,color:c.color,life:.65});}
if(kind==='nova'||kind==='storm'){const radius=skill.range+(p.passive==='geomancer'?.5:0),targets=S.enemies.filter(en=>en.hp>0&&Math.hypot(en.x-p.x,en.y-p.y)<radius).slice(0,skill.maxTargets||99);for(const en of targets){doHit(en,skill.coef);if(kind==='storm')en.poison={ticks:2,timer:1,coef:skill.coef,sourceIndex:index};}fx('nova',p.x,p.y,{color:c.color,life:.8});}
if(kind==='mark'&&e){e.mark=skill.duration;toast('Marca aplicada por8s.');}if(kind==='taunt'&&e){e.taunt=4;e.cooldown=0;toast('Ameaça elevada: alvo provocado.');}if(kind==='crit')S.eye=skill.duration;if(kind==='haste')S.hasteBuff=skill.duration;if(['amp','fury'].includes(kind)){S.timers.amp=skill.duration;S.ampAmount=skill.amp;if(kind==='fury')p.resource-=60;}if(kind==='cloak')S.timers.cloak=skill.duration;
if(kind==='barrier'||kind==='fortress'){S.shield=st.hp*skill.shield;S.timers.barrier=skill.duration;if(kind==='fortress'){S.timers.fortress=6;p.buffs=p.buffs.filter(b=>b.type!=='fortress');p.buffs.push({type:'fortress',until:Date.now()+6000});}toast('Barreira: '+Math.round(S.shield)+'HP.');}
if(kind==='guard'){S.guard=!S.guard;p.resource=100;toast(S.guard?'Guarda ativa. Use a defesa novamente para baixar.':'Guarda encerrada.');}if(kind==='iron')S.buffShield=2;if(kind==='parry')S.timers.parry=p.classId==='LAS'?.6:1;
if(kind==='night'){S.timers.night=6;S.skillCD[0]=0;}if(kind==='horizon')S.timers.horizon=8;if(kind==='dance')S.timers.dance=7;
if(p.classId==='DUE'&&index<5){if(S.lastSkill!==index)p.resource=Math.min(5,p.resource+1);S.lastSkill=index;S.timers.rhythm=6;if(p.resource>=5&&!(S.timers.persistence||0)){p.mp=Math.min(st.mp,p.mp+st.mp*.02);S.timers.persistence=15;}}
if(p.classId==='ARC'&&index<5){S.resonance||=[];if(!S.resonance.includes(index))S.resonance.push(index);if(S.resonance.length>=3){S.timers.amp=4;S.ampAmount=.10;S.resonance=[];}}
S.castingIndex=null;ring(p.x,p.y,c.color);tone(620,.12);}
function updateSkillLabels(){if(!S.player)return;const p=S.player;for(const [id,index] of [['skill1',p.bar[0]],['skill2',p.bar[1]],['skill3',p.bar[2]],['skill4',p.bar[3]],['defense',5],['ultimate',6]]){if(!$(id))continue;const skill=KITS[p.classId][index];$(id).querySelector('small').textContent=skill.name;$(id).querySelector('span').innerHTML=skillArt(skill,p.classId,index===6);$(id).setAttribute('aria-label',skill.name);}}
$('skill1').onclick=()=>useSkill('s1');$('skill2').onclick=()=>useSkill('s2');$('defense').onclick=()=>useSkill('def');$('skill3').onclick=()=>useSkill('s3');$('skill4').onclick=()=>useSkill('s4');$('ultimate').onclick=()=>useSkill('ult');$('spellbookButton').onclick=spellbook;
function attackStart(){if(mode!=='game'||!$('modal').hidden)return;S.nav=false;S.goal=null;chooseTarget();S.attack=true;performBasic();}
function performBasic(){if(!S.player||S.guard||S.cast||S.cd.basic>0)return;const p=S.player,st=stats(p),e=chooseTarget();S.cd.basic=st.interval/(S.hasteBuff>0?1.25:1);S.attackAnim=.5;const inRange=e&&Math.hypot(e.x-p.x,e.y-p.y)<=st.range+((S.timers.horizon||0)>0?2:0);const end=inRange?e:{x:p.x+2.5,y:p.y-.5};if(inRange)hitEnemy(e);else if(S.time-(S.rangeHint||-10)>3){toast(e?'Alvo fora do alcance. Aproxime-se ou toque no inimigo.':'Selecione um inimigo para causar dano.');S.rangeHint=S.time;}fx(st.range>=5?(p.classId==='VIG'?'arrow':'bolt'):'slash',p.x,p.y,{sx:p.x,sy:p.y,tx:end.x,ty:end.y,color:CLASSES[p.classId].color,life:.55});}
function attackStop(){S.attack=false;}
const attackButton=$('attack');attackButton.addEventListener('pointerdown',e=>{e.preventDefault();attackButton.setPointerCapture(e.pointerId);attackStart();});for(const event of ['pointerup','pointercancel','lostpointercapture'])attackButton.addEventListener(event,attackStop);
// A keyboard/accessibility click performs one attack. Pointer hold repeats only while held.
attackButton.onclick=e=>{if(e.detail===0){attackStart();setTimeout(attackStop,180);}};

function usePotion(type){if(mode!=='game'||!$('modal').hidden)return;const p=S.player,st=stats(p);if(S.cd[type]>0){toast('Poção em recarga: '+Math.ceil(S.cd[type])+'s.');return;}if(p.pots[type]<=0){toast('Sem poções. Visite a loja.');return;}if(p[type]>=st[type]){toast(type.toUpperCase()+' já está cheio.');return;}p.pots[type]--;S.cd[type]=20;S.pulses.push({type,maxAtUse:st[type],rate:type==='hp'?.15:.20,left:5,timer:0});toast('Recuperando '+type.toUpperCase()+' em 5 pulsos.');tone(type==='hp'?520:660,.15);save();}
$('hpPotion').onclick=()=>usePotion('hp');$('mpPotion').onclick=()=>usePotion('mp');
function statGrid(){const p=S.player,st=stats(p);return '<p class="classFocus"><b>'+CLASS_PROFILES[p.classId].primary+'</b> · '+CLASS_PROFILES[p.classId].focus+'</p><div class="stats">'+[['Poder total',st.pc.toLocaleString('pt-BR')],['Ataque físico',st.af],['Ataque mágico',st.am],['Defesa',st.def],['HP máximo',st.hp],['MP máximo',st.mp],['Taxa crítica',(st.crit*100).toFixed(1)+'%'],['Limite crítico',(st.maxcrit*100).toFixed(1)+'%'],['Taxa excedente',(Math.max(0,st.critRaw-st.maxcrit)*100).toFixed(1)+'%'],['Dano crítico adicional',((st.critd-1)*100).toFixed(1)+'%'],['Ampliação de espada',(st.ampF*100).toFixed(1)+'%'],['Ampliação de magia',(st.ampM*100).toFixed(1)+'%'],['Penetração física',Math.round(st.penF)],['Penetração mágica',Math.round(st.penM)],['Precisão',Math.round(st.acc)],['Evasão',Math.round(st.evasion)],['Velocidade de ataque','+'+(st.haste*100).toFixed(1)+'%'],['Resistência à taxa crítica',(st.critres*100).toFixed(1)+'%'],['Resistência ao dano crítico',(st.critdres*100).toFixed(1)+'%'],['Resistência à ampliação',(st.ampres*100).toFixed(1)+'%'],['Redução de dano',Math.round(st.dr)],['Redução de recarga',(st.cdr*100).toFixed(1)+'%']].map(v=>`<div class="stat">${v[0]}<b>${v[1]}</b></div>`).join('')+'</div><p class="subtle">Crítico inicial5%, limite50%, dano crítico adicional20%. O limite vem antes das resistências. O poder estima dano útil e sobrevivência contra referência do seu nível; excedentes de crítico e amplificação errada não inflam o ranking.</p>';}

const slotName=s=>({weapon:'Arma principal',secondary:'Arma secundária',armor:'Torso',head:'Cabeça',hands:'Mãos',legs:'Pernas',boots:'Pés',ring1:'Anel1',ring2:'Anel2',neck:'Colar'}[s]||s),optName=s=>({crit:'Chance crítica',critd:'Dano crítico',atk:'Ataque',haste:'Velocidade',ampF:'Ampliação de espada',ampM:'Ampliação de magia',af:'Ataque físico',am:'Ataque mágico',pen:'Penetração',penM:'Penetração mágica',hp:'HP',def:'Defesa',precisao:'Precisão',ten:'Tenacidade',critres:'Resistência à taxa crítica',maxcrit:'Limite de taxa crítica',critdres:'Resistência ao dano crítico',ampres:'Resistência à ampliação',mana:'MP',cdr:'Redução de recarga',dr:'Redução de dano'}[s]||s);
const baseText=i=>Object.entries(i.base).map(([k,v])=>({atk:'Ataque',af:'Ataque físico',am:'Ataque mágico',mp:'MP',hp:'HP',def:'Defesa',acc:'Precisão'}[k])+': '+v).join(' · ');
$('bagButton').onclick=inventory;$('profile').onclick=inventory;
function collection(){const p=S.player;showModal('Coleção de equipamentos','PRÉVIA VISUAL · NÍVEIS175–250',`<p>Selecione uma família para ampliar a aparência da sua classe. Famílias disponíveis no catálogo e na criação. ULTRA exige nível250.</p><div class="collectionTabs">${[['SS+','Vanguarda',175],['SSS','Soberano',195],['SSS+','Transcendente',215],['ULTRA','Primordial',250]].map(([q,n,l])=>`<button class="smallbtn" data-quality="${q}" data-req="${l}" data-title="${n}">${q}<small>${n}</small></button>`).join('')}</div><div class="collectionViewer"><canvas id="collectionPreview" width="400" height="380" aria-label="Prévia da coleção selecionada"></canvas><div><h3 id="collectionName">Primordial +25</h3><p id="collectionInfo">Criação apenas no250. Prévia com assinatura de encantamento.</p><p>Armas da classe, ornamentos de armadura e efeitos em torno da arma. Sem aumentar atributos do personagem nesta tela.</p></div></div><button class="textlink" id="collectionBack">← Voltar ao personagem</button>`);const draw=(q,title,req)=>{$('collectionName').textContent=title+' +25';$('collectionInfo').textContent='Nível'+req+' · '+(q==='ULTRA'?'Somente criação250':'Família '+q)+' · mostruário de aparência';animatedPortrait($('collectionPreview'),p.classId,{quality:q,enchant:25});};document.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>draw(b.dataset.quality,b.dataset.title,b.dataset.req));draw('ULTRA','Primordial',250);$('collectionBack').onclick=inventory;}
function shop(){const p=S.player;showModal('Boticária de Lúmen','MIRA · LOJA COM OURO',`<div class="notice">Saldo: ${p.gold} ouro. Recuperação fácil de obter; elixires são opcionais, com duração de10min e bônus que respeitam os tetos.</div><h3>Recuperação</h3><div class="itemrow"><div class="itemicon">⚗</div><div class="itemdata"><strong>Poção de HP menor ×3</strong><p>15%HP máximo em5s. Recarga20s.</p></div><button data-buy="hp">15 ◈</button></div><div class="itemrow"><div class="itemicon">⚗</div><div class="itemdata"><strong>Poção de MP menor ×3</strong><p>20%MP máximo em5s. Recarga20s.</p></div><button data-buy="mp">12 ◈</button></div><h3>Elixires · 10 minutos</h3>`+[['crit','Mira','+3 pontos de chance crítica'],['critd','Fúria','+5 pontos de dano crítico'],['hp','Vitalidade','+5% HP máximo, sem curar'],['def','Fortaleza','+5% defesa']].map(([k,n,d])=>`<div class="itemrow"><div class="itemdata"><strong>Elixir de ${n}</strong><p>${d}. ${k==='crit'||k==='critd'?'Família ofensiva':'Família defensiva'}.</p></div><button data-buff="${k}">60 ◈ · usar</button></div>`).join('')+'<p class="notice">Economia reduzida para teste. Um buff por família, sem acumular duração. Tempo continua offline. Loja cash e pagamentos não estão implementados nesta alpha.</p>');document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const cost=b.dataset.buy==='hp'?15:12;if(p.gold<cost){toast('Ouro insuficiente.');return;}p.gold-=cost;p.pots[b.dataset.buy]+=3;save();shop();toast('3 poções adicionadas.');});document.querySelectorAll('[data-buff]').forEach(b=>b.onclick=()=>{const type=b.dataset.buff,family=['crit','critd'].includes(type)?'offensive':'defensive';if(p.gold<60){toast('Ouro insuficiente.');return;}const active=p.buffs.find(v=>v.family===family&&v.until>Date.now());if(active&&Date.now()-active.started<60000){toast('Aguarde60s entre elixires da mesma família.');return;}p.gold-=60;p.buffs=p.buffs.filter(v=>v.family!==family);p.buffs.push({type,family,started:Date.now(),until:Date.now()+600000});p.hp=Math.min(p.hp,stats(p).hp);save();shop();toast('Elixir ativo por10min.');});}
$('shopButton').onclick=shop;$('goldButton').onclick=shop;
function journal(){const p=S.player;showModal('Sua jornada','O CHAMADO DAS RELÍQUIAS',`<h3>Capítulo I · O último farol</h3><div class="progressrow"><span>Falar com Ilyra</span><b>${p.quest>0?'✓':'Pendente'}</b></div><div class="progressrow"><span>Derrotar cinco lobos</span><b>${p.quest>=2?'✓':p.kills+' / 5'}</b></div><div class="progressrow"><span>Receber recompensa</span><b>${p.quest>=3?'✓':'Pendente'}</b></div><div class="progressrow"><span>Concluir a cripta</span><b>${p.quest>=4?'✓':'Pendente'}</b></div><h3>Marcos desta alpha</h3><p>${p.killCount} inimigos derrotados · ${p.dungeonClears} masmorra(s) concluída(s) · nível ${p.level}/250.</p><div class="notice">O jogo completo foi planejado até250. Campanha com progressão local até250. Modo solo; grupos e guerras online ainda não estão ativos.</div>`);}
