const miniLayers=new Map();function minimap(){const c=$('minimap'),g=c.getContext('2d'),p=S.player,miniKey=p.zone+':'+(p.region||0);if(!miniLayers.has(miniKey)){const layer=document.createElement('canvas');layer.width=160;layer.height=130;const ctx=layer.getContext('2d');ctx.fillStyle='#132c31';ctx.fillRect(0,0,160,130);for(let x=0;x<40;x++)for(let y=0;y<40;y++){ctx.fillStyle=blocked(x,y,p.zone)?'#28494d':'#75856588';ctx.fillRect(x*4,y*3.25,4,3.25);}if(p.zone==='coast'){ctx.fillStyle='#edcf91';ctx.fillRect(46,37,5,5);ctx.fillStyle='#acdfce';ctx.fillRect(110,27,5,5);}miniLayers.set(miniKey,layer);}g.drawImage(miniLayers.get(miniKey),0,0);for(const e of S.enemies)if(e.hp>0){g.fillStyle='#c88a7288';g.fillRect(e.x*4,e.y*3.25,2,2);}if(S.track&&p.zone==='coast'){const t=p.quest===1?{x:21,y:25}:p.quest===3?portal:npc;g.strokeStyle='#f4d494';g.beginPath();g.arc(t.x*4,t.y*3.25,5+Math.sin(S.time*3)*2,0,Math.PI*2);g.stroke();}g.fillStyle='#eff0ce';g.beginPath();g.arc(p.x*4,p.y*3.25,3,0,Math.PI*2);g.fill();}
window.addEventListener('keydown',e=>{if(document.activeElement?.tagName==='INPUT')return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','tab'].includes(k))e.preventDefault();if(e.repeat)return;if(k==='escape'){if(!$('modal').hidden)closeModal();else if(mode==='game')menu();return;}if(mode!=='game')return;if(!$('modal').hidden)return;keys.add(k);if(k==='1')useSkill('s1');if(k==='2')useSkill('s2');if(k==='3')useSkill('def');if(k==='4')useSkill('s3');if(k==='5')useSkill('s4');if(k==='r')useSkill('ult');if(k==='q')usePotion('hp');if(k==='e')usePotion('mp');if(k==='f')interact();if(k==='i')inventory();if(k===' ')attackStart();});window.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(e.key===' ')attackStop();});window.addEventListener('blur',()=>{keys.clear();joy.x=joy.y=0;attackStop();save()});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();joy.x=joy.y=0;attackStop();save();}last=performance.now();});
