j.addEventListener('pointerdown',e=>{joy.id=e.pointerId;S.nav=false;S.goal=null;j.setPointerCapture(e.pointerId);joyMove(e)});j.addEventListener('pointermove',e=>{if(e.pointerId===joy.id)joyMove(e)});function endJoy(e){if(e.pointerId!==joy.id)return;joy.id=null;joy.x=joy.y=0;S.nav=false;S.goal=null;$('stick').style.transform='';}j.addEventListener('pointerup',endJoy);j.addEventListener('pointercancel',endJoy);
$('world').addEventListener('pointerdown',e=>{if(mode!=='game'||!$('modal').hidden)return;const p=S.player;let target=null,min=44;for(const en of S.enemies){if(en.hp<=0)continue;const pos=r.project(en.x,en.y,18);const d=Math.hypot(pos.x-e.clientX,pos.y-e.clientY);if(d<min){min=d;target=en;}}if(target){S.target=target;S.goal=null;toast(target.name+' selecionado.');return;}const pt=r.unproject(e.clientX,e.clientY);if(p.zone==='coast'&&Math.hypot(pt.x-npc.x,pt.y-npc.y)<1.8){if(S.near==='npc')talk();else S.goal={x:12,y:14};return;}if(p.zone==='coast'&&Math.hypot(pt.x-portal.x,pt.y-portal.y)<2){if(S.near==='portal')dungeonEntry();else S.goal={x:27,y:11};return;}if(!blocked(pt.x,pt.y,p.zone)){S.goal=pt;ring(pt.x,pt.y,'#d7dcb1');}});
function attributesPanel(){const p=S.player;let draft={for:0,int:0,des:0,...p.attributes};showModal('Atributos do personagem',CLASSES[p.classId].name.toUpperCase()+' · 5 PONTOS POR NÍVEL GANHO',`<div class="notice">Nível${p.level}: ${totalPoints(p.level)} pontos no total. Do1ao250:1245 pontos. A distribuição abaixo é uma prévia; só altera seu personagem ao confirmar.</div><details><summary>STATUS COMPLETOS & FOCO DA CLASSE</summary>${statGrid()}</details><div id="attributeEditor"></div><div id="attributePreview"></div><h3>Marcos adicionais</h3><p>FOR: cada25 pontos dá+0,5%HP; cada50dá+1ponto de dano crítico.<br>INT: cada25dá+0,5%MP; cada50dá+1ponto de ampliação mágica.<br>DES: cada25dá+0,25ponto de crítico; cada50dá+0,5%velocidade de ataque.</p><div class="actions"><button id="resetDraft" class="smallbtn">Zerar prévia</button><button id="recommendDraft" class="smallbtn">Sugestão da classe</button><button id="applyDraft" class="smallbtn">Confirmar distribuição</button></div>`);
function renderDraft(){const free=totalPoints(p.level)-usedPoints(draft),scale=ATTRIBUTE_SCALE[p.classId];$('attributeEditor').innerHTML=`<h3>${free} pontos livres</h3>`+[['for','FOR','Força',scale.for+' ataque físico/ponto; +0,3 defesa/ponto'],['int','INT','Inteligência',scale.magic+' ataque mágico/ponto; +4MP; +0,3 defesa/ponto'],['des','DES','Destreza',scale.des+'ataque físico/ponto; +3precisão; +2evasão']].map(([key,title,name,desc])=>`<div class="attributeRow"><div><b>${title} · ${name}</b><small>${desc}</small></div><button data-minus="${key}" aria-label="Reduzir ${title}">−</button><input aria-label="Pontos em ${title}" data-attribute="${key}" type="number" min="0" max="${totalPoints(p.level)}" value="${draft[key]}" inputmode="numeric"><button data-plus="${key}" aria-label="Aumentar ${title}">+</button></div>`).join('');const before=stats(p),after=stats({...p,attributes:draft});$('attributePreview').innerHTML='<h3>Antes → depois</h3><div class="stats">'+[['Ataque físico','af'],['Ataque mágico','am'],['HPmáximo','hp'],['MPmáximo','mp'],['Defesa média','def'],['Precisão','acc'],['Evasão','evasion']].map(([name,key])=>`<div class="stat">${name}<b>${Math.round(before[key])} → ${Math.round(after[key])}</b></div>`).join('')+'</div>';document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{if(free>0){draft[b.dataset.plus]++;renderDraft();}});document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{draft[b.dataset.minus]=Math.max(0,draft[b.dataset.minus]-1);renderDraft();});document.querySelectorAll('[data-attribute]').forEach(input=>input.onchange=()=>{const key=input.dataset.attribute,old=draft[key];draft[key]=Math.max(0,Math.floor(Number(input.value)||0));if(!validAllocation(p.level,draft)){draft[key]=old;toast('Não há pontos suficientes.');}renderDraft();});}
$('resetDraft').onclick=()=>{draft={for:0,int:0,des:0};renderDraft();};$('recommendDraft').onclick=()=>{const total=totalPoints(p.level),ratios={VIG:[2,0,8],ESP:[4,0,6],ARC:[1,8,1],BAS:[7,1,2],RUP:[8,0,2],DUE:[6,0,4],LAS:[4,3,3]}[p.classId];draft={for:Math.floor(total*ratios[0]/10),int:Math.floor(total*ratios[1]/10),des:0};draft.des=total-draft.for-draft.int;renderDraft();};$('applyDraft').onclick=()=>{if(!validAllocation(p.level,draft)){toast('Distribuição inválida.');return;}if(isCombat()){toast('Saia de combate para distribuir.');return;}p.attributes={...draft};p.hp=Math.min(p.hp,stats(p).hp);p.mp=Math.min(p.mp,stats(p).mp);save();closeModal();toast('Atributos aplicados.');};renderDraft();}
function activateLab(){const p=S.player;S.lastCombat=-100;p.x=12;p.y=14;if(!CONTENT){toast('Carregando catálogo. Tente novamente em instantes.');return;}p.testMode=true;p.level=250;p.xp=0;p.gold=50000000;p.shards=5000;p.runes=500;p.energy=100;initAscension(p);p.wallet.cash=100000;addMaterials(p,{'Pluma Astral':100000,'Essência de Aura':100000,'Núcleo de Cataclismo':500});giveReferenceSet();closeModal();announce('LABORATÓRIO250 ATIVO');toast('Recursos de teste liberados. Menu: regiões, itens e habilidades.');save();}
function giveReferenceSet(){const p=S.player;if(!CONTENT)return;for(const src of CONTENT.items.filter(i=>i.class_id===p.classId&&i.tier==='ULT')){const existing=p.bag.find(i=>i.sourceId===src.id);const it=existing||convertItem(src);if(!existing)p.bag.push(it);p.equipped[it.slot]=it.id;}const st=stats(p);p.hp=st.hp;p.mp=st.mp;populate();}
function spellbook(){if(!S.player)return;const p=S.player,kit=KITS[p.classId],doc=CONTENT?.kits[p.classId];showModal('Habilidades & passivas',CLASSES[p.classId].name.toUpperCase()+' · VERSÃO LOCAL DE TESTES',`<div class="notice">Quatro skills na barra, defesa e suprema separadas. Interceptar precisa de aliado; validação de PvP e efeitos de grupo ainda dependem do servidor. ${p.testMode?'Laboratório: todas liberadas.':'Campanha: respeita nível de aprendizado.'}</div>${kit.map((k,i)=>`<div class="skillRow"><div><b>${i>=5?i===5?'DEFESA · ':'SUPREMA · ':''}${k.name}</b><p>${doc?.skills[i]?.description||''}</p><small>${skillAffinity(p.classId,i)} · ${k.coef?'Coeficiente '+k.coef+' · ':''}MP ${k.cost} · Recarga ${k.cd}s</small></div>${i<5?`<button data-assign="${i}" class="smallbtn">${p.bar.includes(i)?'Na barra':'Colocar na barra'}</button>`:''}<button data-cast="${i}" class="smallbtn">Testar</button></div>`).join('')}<h3>Passivas fixas</h3><p>${doc?.passives[0]||''}</p><p class="notice">Ataque físico e mágico, ampliação de espada e magia são calculados separadamente por habilidade. Os coeficientes de Elyndra são próprios; PvP global ainda não está conectado.</p><h3>Escolha uma passiva</h3>${PASSIVE_OPTIONS[p.classId].map(([name,desc,id])=>`<button class="passiveChoice ${p.passive===id?'chosen':''}" data-passive="${id}"><b>${name}${p.passive===id?' ✓':''}</b><span>${desc}</span></button>`).join('')}${p.testMode?'<button class="primary" id="resetCombat">RESTAURAR HP/MP, ENERGIA E RECARGAS</button>':''}`);document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>{const idx=Number(b.dataset.assign);const at=p.bar.indexOf(idx);if(at>=0){toast('Essa habilidade já está na barra.');return;}p.bar[3]=idx;updateSkillLabels();save();spellbook();});document.querySelectorAll('[data-cast]').forEach(b=>b.onclick=()=>{closeModal();castSkill(Number(b.dataset.cast));});document.querySelectorAll('[data-passive]').forEach(b=>b.onclick=()=>{p.passive=b.dataset.passive;save();spellbook();});if($('resetCombat'))$('resetCombat').onclick=()=>{S.skillCD={};S.cast=null;p.hp=stats(p).hp;p.mp=stats(p).mp;p.energy=100;p.resource=p.classId==='RUP'||p.classId==='BAS'?100:p.classId==='LAS'?3:5;closeModal();toast('Estado de combate restaurado para teste.');};}
function atlas(){if(!CONTENT)return;const p=S.player;showModal('Atlas de Elyndra',p.testMode?'LABORATÓRIO · VIAGENS DE TESTE':'CAMPANHA · ROTAS DE PROGRESSÃO',`<div class="notice">${p.testMode?'Atalhos ativos: todos os mapas estão liberados para teste.':'Avance por nível e conclua uma DG da região anterior. O capítulo do farol libera a segunda região.'}</div>${CONTENT.regions.map((region,index)=>{const access=regionAccess(p,index,CONTENT.regions,stats(p).pc);return `<div class="atlasRow"><div><b>${region.name}</b><small>Nv${region.range[0]}–${region.range[1]} · DGs concluídas:${p.regionClears?.[index]||0}</small><small class="${access.ok?'have':'need'}">${access.reason}</small></div><button data-region="${index}" class="smallbtn">${access.ok?'Viajar':'🔒 Bloqueado'}</button></div><div class="dgButtons">${CONTENT.dungeons.filter(d=>d.region===region.name).map(d=>`<button data-dg="${d.id}">${d.name}<small>Nv${d.level_min} · poder${d.public_min_pc.toLocaleString('pt-BR')} · ${d.players===1?'solo':'grupo adaptado para solo'}</small></button>`).join('')}</div>`;}).join('')}`);document.querySelectorAll('[data-region]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.region),access=regionAccess(p,index,CONTENT.regions,stats(p).pc);if(!access.ok){toast(access.reason);return;}p.region=index;p.zone='coast';p.x=12;p.y=14;S.dgName=null;S.dgData=null;populate();closeModal();r.cam={x:p.x,y:p.y};announce(CONTENT.regions[index].name);save();});document.querySelectorAll('[data-dg]').forEach(button=>button.onclick=()=>{const d=CONTENT.dungeons.find(d=>d.id===button.dataset.dg),index=CONTENT.regions.findIndex(region=>region.name===d.region),access=regionAccess(p,index,CONTENT.regions,stats(p).pc);if(!access.ok){toast(access.reason);return;}if(!p.testMode&&(p.level<d.level_min||stats(p).pc<d.public_min_pc)){toast('Requer Nv'+d.level_min+' e poder'+d.public_min_pc.toLocaleString('pt-BR')+'.');return;}p.region=index;setWorldRegion(index);p.zone='dungeon';p.x=11;p.y=12;S.dgName=d.name;S.dgData=d;populate();closeModal();announce(d.name);save();});}
function allItems(){if(!CONTENT){toast('Catálogo carregando.');return;}const p=S.player;showModal('Catálogo de equipamentos','1035 FICHAS · 7 CLASSES · 15 FAMÍLIAS',`<p>Peças da sua classe. Filtre para testar os atributos, opções e encaixes. O visual representa a família; os1035modelos exclusivos ainda não foram produzidos.</p><div class="catalogFilters"><select id="tierFilter" aria-label="Filtrar qualidade"><option value="">Todas as qualidades</option>${[...new Set(CONTENT.items.map(i=>i.tier))].map(q=>`<option>${q}</option>`).join('')}</select><select id="slotFilter" aria-label="Filtrar tipo"><option value="">Todos os tipos</option><option value="arma">Armas</option><option value="armadura">Armaduras</option><option value="joia">Joias</option></select></div><div id="catalogResults"></div>`);function render(){const tier=$('tierFilter').value,kind=$('slotFilter').value,rows=CONTENT.items.filter(i=>i.class_id===p.classId&&(!tier||i.tier===tier)&&(!kind||i.kind===kind));$('catalogResults').innerHTML=rows.map(i=>`<div class="itemrow"><div class="itemdata"><strong>${safe(i.name)}</strong><p>${i.rarity} · Nv${i.level_min}<br>${Object.entries(i.stats).map(([k,v])=>k+':'+v).join(' · ')}</p></div><button data-grant="${i.id}">Obter no LAB</button></div>`).join('');document.querySelectorAll('[data-grant]').forEach(b=>b.onclick=()=>{if(!p.testMode){toast('Ative o laboratório no menu para obter itens de teste.');return;}if(p.bag.length>=80){toast('Mochila cheia. Libere espaço antes de obter outra peça.');return;}const src=CONTENT.items.find(i=>i.id===b.dataset.grant),it=convertItem(src);p.bag.push(it);save();detail(it.id);});}render();$('tierFilter').onchange=render;$('slotFilter').onchange=render;}
function campaignDrop(p,level){if(!CONTENT)return item(p.classId,Math.min(level,p.level),'weapon','D');const eligible=CONTENT.items.filter(i=>i.class_id===p.classId&&i.level_min<=level&&!['SSS','SSS+','ULTRA'].includes(i.rarity)),best=Math.max(...eligible.map(i=>i.level_min),1),pool=eligible.filter(i=>i.level_min===best);return pool.length?convertItem(pool[Math.floor(Math.random()*pool.length)]):item(p.classId,1);}
const SLOTS=['head','neck','armor','hands','weapon','secondary','legs','boots','ring1','ring2'];
