function inventory(){const p=S.player;if(!p)return;showModal('Equipamento & inventário',CLASSES[p.classId].name+' · Nv'+p.level+' · '+p.gold.toLocaleString('pt-BR')+' ouro',`<div class="inventoryLayout"><section class="paperdoll"><canvas id="equipmentPreview" width="400" height="380" aria-label="Personagem com equipamentos atuais"></canvas><div class="dollSlots">${SLOTS.filter(slot=>!(slot==='secondary'&&p.classId==='RUP')).map(slot=>{const i=p.bag.find(i=>i.id===p.equipped[slot]);return `<button class="dollSlot ${i?'rarity-'+i.quality.replaceAll('+','p'):''}" data-equipped="${i?.id||''}" data-slot="${slot}" aria-label="${slotCaption(slot)}: ${i?itemName(i):'vazio'}">${i?itemArt(i,p.classId,36):'<span>＋</span>'}<small>${slotCaption(slot)}</small>${i?.enchant?'<em>+'+i.enchant+'</em>':''}</button>`}).join('')}</div><div class="paperPower">Poder <b>${stats(p).pc.toLocaleString('pt-BR')}</b><button id="attributesButton">${totalPoints(p.level)-usedPoints(p.attributes)} pontos livres ↗</button></div></section><section class="bagPane"><div class="bagHeading"><b>Mochila <small>${p.bag.length}/80</small></b><select id="bagFilter" aria-label="Filtrar mochila"><option value="all">Todos</option><option value="usable">Equipáveis</option><option value="upgrade">Aumentam poder</option><option value="weapon">Armas</option><option value="armor">Armaduras</option><option value="jewelry">Joias</option><option value="materials">Materiais</option></select></div><div class="bagGrid" id="bagGrid"></div></section></div><div class="panelFooter"><button id="inventoryForge">Forja & aprimorar</button><button id="inventoryCatalog">Catálogo & receitas</button><button id="inventoryStats">Ver atributos</button><button id="inventoryAscension">Asas & aura</button></div>`);document.querySelectorAll('[data-equipped]').forEach(b=>b.onclick=()=>{if(b.dataset.equipped)detail(b.dataset.equipped);else{$('bagFilter').value=['ring1','ring2','neck'].includes(b.dataset.slot)?'jewelry':['weapon','secondary'].includes(b.dataset.slot)?'weapon':'armor';drawBag();toast('Toque numa peça da mochila para equipar.');}});animatedPortrait($('equipmentPreview'),p.classId,appearanceFor(p));function drawBag(){const filter=$('bagFilter').value,items=p.bag.filter(i=>filter==='all'||filter==='usable'&&i.level<=p.level&&p.equipped[i.slot]!==i.id||filter==='upgrade'&&i.level<=p.level&&stats({...p,equipped:{...p.equipped,[i.slot]:i.id}}).pc>stats(p).pc||filter==='weapon'&&['weapon','secondary'].includes(i.slot)||filter==='armor'&&['head','armor','hands','legs','boots'].includes(i.slot)||filter==='jewelry'&&['ring1','ring2','neck'].includes(i.slot)).sort((a,b)=>Number(p.equipped[b.slot]===b.id)-Number(p.equipped[a.slot]===a.id)||b.level-a.level);if(filter==='materials'){$('bagGrid').innerHTML=Object.entries(p.materials||{}).filter(([k,v])=>v>0).map(([k,v])=>`<div class="materialCell"><b>${safe(k)}</b><span>×${v}</span></div>`).join('')+`<div class="materialCell"><b>Cristais</b><span>×${p.shards}</span></div><div class="materialCell"><b>Runas</b><span>×${p.runes}</span></div>`;return;}$('bagGrid').innerHTML=items.length?items.map(i=>`<button class="bagItem rarity-${i.quality.replaceAll('+','p')}" data-item="${i.id}" aria-label="${itemName(i)}, ${i.quality}, nível${i.level}">${itemArt(i,p.classId,42)}<em>${i.enchant?'+'+i.enchant:i.quality}</em>${p.equipped[i.slot]===i.id?'<mark>E</mark>':''}<small>${safe(i.name)}</small><span class="itemState">${p.equipped[i.slot]===i.id?'EM USO':p.level<i.level?'🔒 Nv'+i.level:'EQUIPÁVEL'}</span></button>`).join(''):'<p class="emptyState">Nenhum item nesta categoria.<br>Obtenha peças em missões, DGs ou na forja.</p>';document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>detail(b.dataset.item));}drawBag();$('bagFilter').onchange=drawBag;$('attributesButton').onclick=attributesPanel;$('inventoryForge').onclick=()=>forgePanel('enchant');$('inventoryCatalog').onclick=()=>forgePanel('craft');$('inventoryAscension').onclick=()=>ascensionPanel();$('inventoryStats').onclick=()=>{showModal('Status do personagem',CLASSES[p.classId].name+' · Nível'+p.level,statGrid()+'<button class="smallbtn" id="returnBag">← Inventário</button>');$('returnBag').onclick=inventory;};}
function detail(id){const p=S.player,i=p.bag.find(v=>v.id===id);if(!i)return;const equipped=p.equipped[i.slot]===id,price=enchantPrice(i.enchant),after=stats({...p,equipped:{...p.equipped,[i.slot]:id}}),current=stats(p),delta=after.pc-current.pc;showModal(i.name+(i.enchant?' +'+i.enchant:''),`${i.quality} · ${slotCaption(i.slot)} · Nv${i.level} · ${equipped?'EQUIPADO':'NA MOCHILA'}`,`<div class="itemSheet"><div class="itemHero rarity-${i.quality.replaceAll('+','p')}">${itemArt(i,p.classId,116)}<b>${i.quality} ${i.enchant?'+'+i.enchant:''}</b><small>${equipped?'Equipado no personagem':p.level<i.level?'Requer nível'+i.level:(delta>=0?'+':'')+delta.toLocaleString('pt-BR')+' poder ao equipar'}</small></div><div class="itemNumbers"><h3>Atributos básicos</h3><div class="baseStats">${Object.entries(i.base).filter(([k,v])=>v&&!(k==='atk'&&(i.base.af!=null||i.base.am!=null))).map(([k,v])=>`<span>${{atk:'Ataque',af:'Ataque físico',am:'Ataque mágico',mp:'MP',hp:'HP',def:'Defesa',acc:'Precisão'}[k]||k}<b>${(v*(1+i.enchant*({atk:.012,af:.012,am:.012,def:.012,hp:.008,acc:.006}[k]||0))).toLocaleString('pt-BR',{maximumFractionDigits:1})}</b></span>`).join('')}</div><h3>Opções adicionais <small>${i.options.length}/3</small></h3>${i.options.length?i.options.map(a=>`<div class="affix">${optName(a.type)} <b>+${valueText(a.type,a.value)}</b></div>`).join(''):'<p class="subtle">Comum: somente atributos básicos.</p>'}<h3>Encaixes ${i.runes.length}/${i.slots}</h3><div class="runeSlots">${Array.from({length:i.slots},(_,n)=>`<span>${i.runes[n]?'◆ '+optName(i.runes[n].type)+' +'+valueText(i.runes[n].type,runeValue(i,i.runes[n],n)):'◇ Livre'}</span>`).join('')||'<small>Sem encaixes nesta qualidade.</small>'}</div></div></div><div class="itemActions"><button class="primary" id="equipItem">${equipped?'DESEQUIPAR':'EQUIPAR'}</button><button class="smallbtn" id="enchantItem" ${i.enchant>=25?'disabled':''}>Aprimorar +${Math.min(25,i.enchant+1)}<small>${price.gold.toLocaleString('pt-BR')} ouro · ${price.crystals} cristal · ${Math.round(price.chance*100)}%</small></button><button class="smallbtn" id="runeItem" ${i.slots<=i.runes.length||p.runes<1?'disabled':''}>Inserir runa<small>${p.runes} disponível(is)</small></button></div><div class="itemActions"><button class="smallbtn cashAction" id="cashEnchantItem" ${i.enchant>=25?'disabled':''}>TENTAR COM CASH<small>Comprar faltantes + aprimorar</small></button>${canExtend(p.level,i)?'<button class="smallbtn cashAction" id="cashExtendItem">3º SLOT COM CASH<small>Extensor + aplicação</small></button>':''}</div><details class="itemMore"><summary>Materiais, garantia e terceiro slot</summary><p>Seu saldo: ${p.gold.toLocaleString('pt-BR')} ouro · ${p.shards}cristais. Garantia ${i.attempts||0}/${price.pity}. Aprimoramento cresce só a base; não multiplica opções nem runas.</p><p>Terceiro slot exige175+, SS+ ou melhor, dois slots naturais e Extensor Astral. Ao estender, cada opção usa o valor estendido do grau: AMP7%→8/9/10%; no grau250,8%→11%.</p>${!equipped?'<button class="smallbtn" id="sellItem">Vender esta peça por15ouro</button>':''}${p.testMode?'<button class="smallbtn" id="labEnchant">TESTE: visualizar +25</button>':''}${canExtend(p.level,i)?'<button class="smallbtn" id="extendItem">Estender terceiro slot · '+(p.materials?.['Extensor Astral']||0)+' extensor(es)</button>':''}${p.testMode&&canExtend(p.level,i)?'<button class="smallbtn" id="labExtend">TESTE: abrir terceiro slot</button>':''}</details><button id="backInventory" class="textlink">← Voltar aos itens</button>`);$('equipItem').onclick=()=>{const result=applyEquipment(p,id,!equipped,isCombat());if(!result.ok){toast(result.reason);return;}save();detail(id);toast(equipped?'Item desequipado.':'Item equipado.');};$('enchantItem').onclick=()=>{if(isCombat()){toast('Saia de combate para aprimorar.');return;}const result=performEnchant(p,i);if(!result.ok){toast(result.reason);return;}save();detail(id);toast(result.success?'Sucesso! '+i.name+' +'+i.enchant:'Falhou, sem perda do item. Garantia '+i.attempts+'/'+result.price.pity+'.');if(result.success){S.levelPulse=.8;tone(950,.25);}};$('runeItem').onclick=()=>socketRune(id);if($('sellItem'))$('sellItem').onclick=()=>{showModal('Vender equipamento','CONFIRME A PEÇA',`<p>${itemName(i)} será removido da mochila. Você receberá15ouro.</p><button class="primary" id="confirmSale">CONFIRMAR VENDA</button><button class="textlink" id="cancelSale">Cancelar</button>`);$('confirmSale').onclick=()=>{if(isCombat()){toast('Saia de combate.');return;}p.bag=p.bag.filter(v=>v.id!==id);p.gold+=15;save();inventory();};$('cancelSale').onclick=()=>detail(id);};if($('labEnchant'))$('labEnchant').onclick=()=>{i.enchant=25;save();detail(id);};if($('extendItem'))$('extendItem').onclick=()=>{const out=extendEquipment(p,i,isCombat());if(!out.ok){toast(out.reason);return;}save();detail(id);toast('Terceiro slot aberto. Valores estendidos aplicados.');};if($('labExtend'))$('labExtend').onclick=()=>{if(canExtend(p.level,i)){i.slots=3;save();detail(id);}};$('cashEnchantItem').onclick=()=>premiumDialog('enchant',i,()=>detail(id));if($('cashExtendItem'))$('cashExtendItem').onclick=()=>premiumDialog('extend',i,()=>detail(id));$('backInventory').onclick=inventory;}
function evolutionHub(){const p=S.player;showModal('Evolução','CAMPANHA · NÍVEL'+p.level+' / 250',`<div class="growthSummary"><strong>${p.testMode?'Laboratório: nível máximo':p.level===250?'Nível máximo':p.xp.toLocaleString('pt-BR')+' / '+maxXP(p.level).toLocaleString('pt-BR')+'XP'}</strong><div class="wideBar"><i style="width:${p.testMode?100:p.xp/maxXP(p.level)*100}%"></i></div><p>${p.testMode?'Laboratório não ganhaXP. Comece uma campanha para evoluir.':'Complete missões, contratos, DGs e chefes para subir. Cada nível ganho libera5 pontos.'}</p></div><div class="evolutionCards"><button id="evoWings"><b>Asas do Firmamento</b><span>Nível${p.wings?.rank||0}/50 · plumas e brilho</span></button><button id="evoAura"><b>Aura da Origem</b><span>Nível${p.aura?.rank||0}/50 · identidade e poder</span></button><button id="evoAttributes"><b>FOR · INT · DES</b><span>${totalPoints(p.level)-usedPoints(p.attributes)} pontos livres</span></button><button id="evoEnchant"><b>Aprimorar</b><span>Selecione a peça · +0 até +25</span></button><button id="evoCraft"><b>Fabricar equipamento</b><span>Receita · materiais · requisito</span></button><button id="evoShop"><b>Poções & elixires</b><span>Recuperação e buffs por ouro</span></button><button id="evoJournal"><b>Jornada & contratos</b><span>${(p.huntCount||0)%5}/5inimigos no contrato</span></button><button id="evoAtlas"><b>Regiões & DGs</b><span>Escolha uma faixa de nível</span></button></div>`);$('evoWings').onclick=()=>ascensionPanel('wings');$('evoAura').onclick=()=>ascensionPanel('aura');$('evoAttributes').onclick=attributesPanel;$('evoEnchant').onclick=()=>forgePanel('enchant');$('evoCraft').onclick=()=>forgePanel('craft');$('evoShop').onclick=shop;$('evoJournal').onclick=journal;$('evoAtlas').onclick=atlas;}
function forgePanel(tab='enchant'){if(!CONTENT){toast('Carregando receitas…');return;}const p=S.player;showModal('Forja de Borun','OURO '+p.gold.toLocaleString('pt-BR')+' · CRISTAIS '+p.shards,`<div class="panelTabs"><button id="tabEnchant" class="${tab==='enchant'?'selected':''}">Aprimorar</button><button id="tabCraft" class="${tab==='craft'?'selected':''}">Fabricar</button><button id="tabMaterials" class="${tab==='materials'?'selected':''}">Materiais</button></div><div id="forgeContent"></div>`);$('tabEnchant').onclick=()=>forgePanel('enchant');$('tabCraft').onclick=()=>forgePanel('craft');$('tabMaterials').onclick=()=>forgePanel('materials');const body=$('forgeContent');if(tab==='enchant'){body.innerHTML='<p class="subtle">Selecione uma peça. A base aumenta; opções e runas são preservadas.</p><div class="forgeItems">'+p.bag.map(i=>`<button data-forge-item="${i.id}">${itemArt(i,p.classId,42)}<span><b>${itemName(i)}</b><small>${slotCaption(i.slot)} · ${i.quality} · +${i.enchant}</small></span><em>→</em></button>`).join('')+'</div>';document.querySelectorAll('[data-forge-item]').forEach(b=>b.onclick=()=>detail(b.dataset.forgeItem));}else if(tab==='materials'){body.innerHTML='<p class="subtle">L:minério/tecido · E:essência · N:núcleo deDG · K:cristal · P:prova. O número indica a região.</p><div class="materialGrid">'+Object.entries(p.materials).filter(([k,v])=>v>0).map(([key,n])=>`<div class="materialCell"><b>${safe(key)}</b><span>×${n}</span></div>`).join('')+'</div>';}else{body.innerHTML='<div class="catalogFilters"><select id="craftTier" aria-label="Família da receita">'+[...new Set(CONTENT.items.map(i=>i.tier))].map(t=>`<option value="${t}">${t}</option>`).join('')+'</select><span>Receitas exclusivas da sua classe</span></div><div id="craftRecipes"></div>';function recipes(){const tier=$('craftTier').value;const rows=CONTENT.items.filter(i=>i.class_id===p.classId&&i.tier===tier);$('craftRecipes').innerHTML=rows.map(src=>{const candidate=convertItem(src),check=craftCheck(p,src);return `<div class="recipeRow">${itemArt(candidate,p.classId,44)}<div><b>${safe(src.name)}</b><small>${src.rarity} · Nv${src.level_min}</small><p>${Object.entries(src.recipe_components||{}).map(([k,n])=>`<span class="${(k==='gold'?p.gold:p.materials[k]||0)>=n?'have':'need'}">${k==='gold'?'Ouro':safe(k)} ${k==='gold'?p.gold:p.materials[k]||0}/${n}</span>`).join(' · ')}</p></div><button class="smallbtn" data-craft="${src.id}">${p.level<src.level_min?'Nv'+src.level_min:'Ver receita'}</button></div>`}).join('');document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{const src=CONTENT.items.find(i=>i.id===b.dataset.craft),check=craftCheck(p,src),preview=convertItem(src);showModal('Fabricar: '+src.name,src.rarity+' · Nv'+src.level_min,`<div class="craftConfirm">${itemArt(preview,p.classId,96)}<div><p>${src.visual}</p><p>${Object.entries(src.recipe_components).map(([k,v])=>safe(k)+': '+v).join(' · ')}</p><p class="${check.ok?'have':'need'}">${check.ok?'Você possui os materiais.':check.reason}</p></div></div><button class="primary" id="confirmCraft">FABRICAR PEÇA</button><button class="textlink" id="backCraft">← Voltar à forja</button>`);$('confirmCraft').onclick=()=>{if(isCombat()){toast('Saia de combate para fabricar.');return;}const result=craft(p,src);if(!result.ok){toast(result.reason);return;}save();tone(900,.2);detail(result.item.id);toast('Equipamento fabricado e colocado na mochila.');};$('backCraft').onclick=()=>forgePanel('craft');});}recipes();$('craftTier').onchange=recipes;}}
$('forgeButton').onclick=evolutionHub;$('atlasQuick').onclick=atlas;$('freePoints').onclick=attributesPanel;$('minimapButton').onclick=atlas;

function frame(now){const elapsed=(now-last)/1000;last=now;if(document.hidden){requestAnimationFrame(frame);return;}frameTick+=elapsed;const fps=quality==='economy'?30:30;if(frameTick<1/fps){requestAnimationFrame(frame);return;}const dt=Math.min(frameTick,.08);frameTick%=1/fps;const rotated=mode==='game'&&innerWidth<innerHeight&&innerWidth<700;if(!rotated)update(dt);const started=performance.now();r.render(S,dt);if(portraitPreview?.canvas.isConnected&&portraitPreview.canvas.getClientRects().length)r.portrait(portraitPreview.canvas,portraitPreview.id,portraitPreview.appearance);const renderMs=performance.now()-started;renderCount++;renderSeconds+=dt;uiTick+=dt;if(uiTick>.25&&mode==='game'){updateHUD();$('performanceStatus').textContent='ALVO30 · '+renderMs.toFixed(1)+'ms';$('heroMarker').hidden=false;const point=r.project(S.player.x,S.player.y);$('heroMarker').style.left=point.x+'px';$('heroMarker').style.top=point.y+'px';$('heroMarker').dataset.visible='true';$('heroMarker').dataset.renderMs=renderMs.toFixed(2);$('heroMarker').dataset.groundDraws='0';uiTick=0;}requestAnimationFrame(frame);}requestAnimationFrame(frame);$('loading').hidden=true;$('welcome').hidden=false;
// Small, read-only diagnostics for automated checks and support. No fake online state.
window.elyndra={state:()=>({mode,zone:S.player?.zone,level:S.player?.level,hp:S.player?.hp,quest:S.player?.quest,enemies:S.enemies.filter(e=>e.hp>0).length,pc:S.player?stats(S.player).pc:null}),version:'0.6.0'};

for(const name of ['dblclick','contextmenu','gesturestart','gesturechange'])document.addEventListener(name,e=>{if(document.body.dataset.playing==='true'&&(!e.target.closest('input,select,textarea')))e.preventDefault();},{passive:false});
document.addEventListener('touchmove',e=>{if(document.body.dataset.playing==='true'&&!e.target.closest('#modalBody'))e.preventDefault();},{passive:false});

function socketRune(id){const p=S.player,i=p.bag.find(v=>v.id===id);if(!i||i.runes.length>=i.slots||p.runes<1)return;if(isCombat()){toast('Saia de combate para inserir runas.');return;}const choices=runeChoices(i,p.classId),grade=socketGrade(i);showModal('Núcleos de atributo',i.name+' · '+grade.name+' · '+p.runes+' NÚCLEOS',`<div class="socketBanner"><span class="runeCrystal">◆</span><div><b>Encaixe ${i.runes.length+1} de ${i.slots}</b><p>Escolha a opção. Consome1núcleo. O valor depende do grau e da extensão da peça.</p></div></div><div class="runeChoices">${choices.map(r=>`<button data-rune-type="${r.type}"><span>◆</span><div><b>${optName(r.type)}</b><small>${grade.name} · ${i.slots===3?'estendido':'normal'}</small></div><strong>+${valueText(r.type,r.value)}</strong></button>`).join('')}</div><details><summary>Tabela de ampliação por grau</summary><table class="runeTable"><tr><th>Grau</th><th>Normal</th><th>Estendido</th></tr>${SOCKET_GRADES.map(g=>`<tr><td>${g.name} · Nv${g.min}+</td><td>${g.amp[0]}%</td><td>${g.amp[1]}%</td></tr>`).join('')}</table><p>Mapeamento dos graus para níveis é próprio deElyndra. Armas unificadas doRuptor têm valores dobrados. Três opções iguais são permitidas; crítico usa os totais específicos da tabela.</p></details><button class="textlink" id="socketBack">← Voltar ao item</button>`);document.querySelectorAll('[data-rune-type]').forEach(b=>b.onclick=()=>{const entry=choices.find(v=>v.type===b.dataset.runeType);if(!entry||i.runes.length>=i.slots||p.runes<1)return;i.runes.push({type:entry.type,rule:'cabal05',value:entry.value});p.runes--;save();detail(id);toast('Núcleo inserido. Atributos e poder atualizados.');});$('socketBack').onclick=()=>detail(id);}

function ascensionPanel(kind='wings',previewRank=null){
 const p=S.player;initAscension(p);const state=p[kind],isW=kind==='wings',cost=ascensionCost(p,kind),shown=previewRank??(state.rank||1),max=state.rank>=50,tier=ascensionTier(shown),quote=premiumQuote(p,kind);
 showModal(isW?'Asas do Firmamento':'Aura da Origem','EVOLUÇÃO '+state.rank+'/50 · '+ascensionForm(kind,state.rank),`<div class="panelTabs"><button id="wingTab" class="${isW?'selected':''}">Asas</button><button id="auraTab" class="${!isW?'selected':''}">Aura</button></div><div class="rarityTrack">${ASCENSION_TIERS.map(t=>`<button data-preview-tier="${Math.max(1,t.min)}" class="${tier.key===t.key?'selected':''}" style="--tier:${t.color}">${t.name}<small>${t.min||1}${t.min===50?'':'–'+(t.min===0?9:t.min+9)}</small></button>`).join('')}</div><div class="ascensionLayout" style="--relic-color:${tier.color}"><div class="ascensionPreview">${isW&&shown?divineWings(shown,state.style):''}${shown?auraRelic(isW?(p.aura?.rank||1):shown,isW?p.aura?.style:state.style):''}<canvas id="ascensionPreview" width="400" height="380" aria-label="Personagem com relíquia animada"></canvas><strong>${ascensionForm(kind,shown)}</strong><small>${shown===state.rank?'ESTÁGIO EQUIPADO':'PRÉVIA VISUAL · NÃO EQUIPADA'}</small></div><div class="ascensionInfo"><div class="evolutionTier">${tier.name.toUpperCase()} · ${shown}/50</div><div class="rankPips">${Array.from({length:50},(_,n)=>`<i class="${n<state.rank?'on':''}"></i>`).join('')}</div><h3>${isW?'Plumas → cristal → serafim → prisma':'Centelha → runas → coroa → domínio'}</h3><p>${isW?'Níveis1–10: +1,2% ataque e20 precisão por nível. De11–50: +0,3% ataque e5 precisão por nível. Total no50: +24% ataque e400 precisão.':'Níveis1–10: +0,8%HP, +1,2% defesa e+0,5p.p. dano crítico por nível. De11–50: um quarto desse ganho. Total: +16%HP, +24% defesa e+10p.p. dano crítico.'}</p><div class="ascensionCost">${max?'<b>Evolução máxima · Ultra Primordial</b>':`<b>Próximo nível: ${cost.rank} · requer Nv${cost.level}</b><span>Ouro ${p.gold.toLocaleString('pt-BR')} / ${cost.gold.toLocaleString('pt-BR')}</span><span>${cost.material}: ${p.materials[cost.material]||0}/${cost.count}</span>${cost.cores?'<span>Núcleos: '+(p.materials['Núcleo de Cataclismo']||0)+'/'+cost.cores+'</span>':''}`}</div><button class="primary" id="evolveAscension" ${max?'disabled':''}>${state.rank?'EVOLUIR':'DESPERTAR'} COM MATERIAIS</button><button class="smallbtn cashAction" id="cashAscension" ${!quote.ok?'disabled':''}>EVOLUIR COM CASH<small>${quote.ok?quote.price.toLocaleString('pt-BR')+' cash · compra faltantes + evolui':safe(quote.reason)}</small></button><label class="appearanceToggle"><input type="checkbox" id="showAscension" ${state.visible!==false?'checked':''}> Mostrar no personagem</label>${p.testMode?'<button class="labVisualButton" id="labRelic">LAB: EQUIPAR EVOLUÇÃO DA PRÉVIA</button>':''}</div></div><div class="styleChoices">${Object.entries(STYLES).map(([key,style])=>{const locked=key==='void'&&!p.appearances.includes('a-eclipse')||key==='infernal'&&!p.appearances.includes('w-eclipse');return `<button data-ascension-style="${key}" class="${state.style===key?'selected':''}" style="--style-color:${style.color}">${locked?'🔒 ':''}${style.name}</button>`;}).join('')}</div><details><summary>Materiais, cash e progressão</summary><p>50 evoluções em cada relíquia. Comum1–9, Raro10–19, Épico20–29, Lendário30–39, Divino40–49, Ultra50. O Ultra exige personagem250. Caça, DGs e chefes dão plumas e essências; Cataclismos dão núcleos, usados a partir da evolução35. Aparências mudam a cor; a raridade define forma, camadas e intensidade.</p><p>Cash compra somente o ouro e os materiais faltantes, cobra serviço de150cash e evolui em uma transação. O requisito de nível continua obrigatório. Aparência e visibilidade não mudam os bônus.</p></details><div class="ascensionInspect"><label>Prévia de evolução<select id="previewAscension" aria-label="Prévia do nível de evolução">${Array.from({length:51},(_,n)=>`<option value="${n}" ${n===shown?'selected':''}>${n} · ${ascensionForm(kind,n)}</option>`).join('')}</select></label><button id="ascensionBosses" class="smallbtn">Chefes & materiais</button></div><button class="visualDemoButton" id="relicDemo">MOSTRUÁRIO: ESPADA LENDÁRIA & SKILLS EM AÇÃO →</button>`);
 $('wingTab').onclick=()=>ascensionPanel('wings');$('auraTab').onclick=()=>ascensionPanel('aura');
 const ap=appearanceFor(p);ap.wings={rank:0};ap.aura={rank:0};animatedPortrait($('ascensionPreview'),p.classId,ap);
 $('evolveAscension').onclick=()=>{if(isCombat()){toast('Saia de combate para evoluir.');return;}const out=evolveAscension(p,kind);if(!out.ok){toast(out.reason);return;}save();ascensionPanel(kind);announce((isW?'ASAS':'AURA')+' · NÍVEL '+p[kind].rank);};
 $('cashAscension').onclick=()=>premiumDialog(kind,null,()=>ascensionPanel(kind));
 $('showAscension').onchange=e=>{state.visible=e.target.checked;save();ascensionPanel(kind);};
 $('previewAscension').onchange=e=>ascensionPanel(kind,Number(e.target.value));
 document.querySelectorAll('[data-preview-tier]').forEach(b=>b.onclick=()=>ascensionPanel(kind,Number(b.dataset.previewTier)));
 document.querySelectorAll('[data-ascension-style]').forEach(b=>b.onclick=()=>{const key=b.dataset.ascensionStyle;if(key==='void'&&!p.appearances.includes('a-eclipse')||key==='infernal'&&!p.appearances.includes('w-eclipse')){toast('Aparência disponível na loja cash.');return;}state.style=key;save();ascensionPanel(kind,shown);});
 if($('labRelic'))$('labRelic').onclick=()=>{state.rank=shown;state.visible=true;save();ascensionPanel(kind);toast('LAB: evolução'+shown+' equipada para teste.');};
 $('ascensionBosses').onclick=()=>bossLab();$('relicDemo').onclick=relicGallery;
}
function animatedPortrait(canvas,id,appearance={}){portraitPreview={canvas,id,appearance};r.portrait(canvas,id,appearance);}
function premiumDialog(action,item,back){const p=S.player,q=premiumQuote(p,action,item);if(!q.ok){toast(q.reason);return;}const title=action==='enchant'?'Tentativa de encantamento':action==='extend'?'Abrir terceiro slot':action==='wings'?'Evoluir asas':'Evoluir aura';showModal(title,'SERVIÇO CASH · '+(p.testMode?'MOEDA DE TESTE':'CARTEIRA DO JOGO'),`<div class="premiumConfirm"><small>${item?safe(item.name):ascensionForm(action,p[action].rank)}</small><strong>${q.price.toLocaleString('pt-BR')} CASH</strong><p>${q.summary}</p><p>Saldo: ${p.wallet.cash.toLocaleString('pt-BR')} cash. Itens existentes são usados primeiro. Opções adicionais e atributos das runas não mudam com encantamento.</p></div><button class="primary cashAction" id="confirmPremium" ${p.wallet.cash<q.price?'disabled':''}>CONFIRMAR COMPRA E APLICAR</button><button class="textlink" id="backPremium">← Voltar</button>`);$('backPremium').onclick=back;$('confirmPremium').onclick=()=>{const out=premiumApply(p,action,item,isCombat());if(!out.ok){toast(out.reason);return;}save();back();toast(out.success===false?'Tentativa falhou. Garantia acumulada; equipamento preservado.':'Evolução aplicada · '+out.price.toLocaleString('pt-BR')+' cash.');};}
function relicGallery(){showModal('Relíquias de Elyndra','ARTE ORIGINAL · METAL & TECNOMAGIA',legendarySwordCard()+'<p>Teste as habilidades na arena para ver projéteis, explosões, trajetórias e a recarga radial em combate.</p><button class="primary" id="demoSkills">ARENA DE SKILLS DA SUA CLASSE</button><button class="textlink" id="backRelics">← Asas e aura</button>');$('backRelics').onclick=()=>ascensionPanel();$('demoSkills').onclick=()=>{if(!S.player.testMode){toast('Entre no Laboratório Nv250 pelo menu para liberar todas as skills.');return;}skillArena();};}
function skillArena(){const p=S.player;p.zone='dungeon';p.x=17;p.y=14;S.dgData=null;S.bossEncounter=null;S.dungeonWon=true;S.dgName='Arena de habilidades';S.decor=decorations('dungeon');S.enemies=[];S.loot=[];S.effects=[];const ranged=CLASSES[p.classId].range>=5,enemy=spawn(ranged?23:19,ranged?15:14,'wisp',p.level,true);enemy.training=true;enemy.name='Sentinela de treino';enemy.maxHp=enemy.hp=Math.max(5000000,stats(p).atk*1000);enemy.shield=0;enemy.atk=1;enemy.speed=0;enemy.homeX=enemy.x;enemy.homeY=enemy.y;S.target=enemy;S.skillCD={};p.energy=100;p.resource=p.classId==='LAS'?3:p.classId==='RUP'||p.classId==='BAS'?100:5;p.hp=stats(p).hp;p.mp=stats(p).mp;S.lastCombat=-100;S.goal=null;closeModal();r.cam={x:p.x,y:p.y};toast('LAB: alvo de treino selecionado. Toque nas skills; ataque só enquanto pressionado.');updateHUD();}
function cashShop(tab='items'){const p=S.player;initAscension(p);showModal('Empório Astral','OURO '+p.gold.toLocaleString('pt-BR')+' · CASH '+p.wallet.cash.toLocaleString('pt-BR')+(p.testMode?' · TESTE':''),`<div class="panelTabs"><button id="cashItems" class="${tab==='items'?'selected':''}">Loja cash</button><button id="cashRecharge" class="${tab==='recharge'?'selected':''}">Recarga</button></div><div class="walletStrip"><div><small>OURO · obtido jogando</small><b>◈ ${p.gold.toLocaleString('pt-BR')}</b></div><div><small>CASH ${p.testMode?'DE TESTE':'· moeda premium'}</small><b>✧ ${p.wallet.cash.toLocaleString('pt-BR')}</b></div></div>${tab==='items'?`<button class="visualDemoButton" id="cashServices">SERVIÇOS: EVOLUIR, APRIMORAR & TERCEIRO SLOT →</button><div class="cashProducts">${CASH_PRODUCTS.map(item=>`<article><span>${item.kind==='appearance'?'✦':'◆'}</span><div><b>${item.name}</b><p>${item.description}</p><button data-cash-product="${item.id}" class="smallbtn">${p.appearances.includes(item.id)?'Já adquirido':item.price+' cash'}</button></div></article>`).join('')}</div>`:`<div class="notice">A recarga com dinheiro real ainda não está conectada. Nenhuma cobrança é realizada e nenhum pagamento é simulado. Cash real precisa de conta, servidor e provedor de pagamento.</div><div class="rechargePacks">${[500,1200,3000].map(n=>`<article><b>${n.toLocaleString('pt-BR')} CASH</b><small>Preço ainda não definido</small><button disabled>Pagamento indisponível</button></article>`).join('')}</div>${p.testMode?'<button class="smallbtn" id="testCashCredit">LAB: adicionar100.000cash de teste</button>':''}`}`);if($('cashServices'))$('cashServices').onclick=()=>{showModal('Serviços do Empório','COMPRA AUTOMÁTICA DE MATERIAIS','<div class="menugrid"><button id="serviceWings">Evoluir asas</button><button id="serviceAura">Evoluir aura</button><button id="serviceGear">Encantar ou abrir terceiro slot</button></div><p>O preço aparece antes da aplicação. Terceiro slot:25.000cash pelo extensor +500pela aplicação. Requer175+, SS+ ou superior. Encantamento compra faltantes para uma tentativa com a chance e a garantia normais.</p>');$('serviceWings').onclick=()=>ascensionPanel('wings');$('serviceAura').onclick=()=>ascensionPanel('aura');$('serviceGear').onclick=inventory;};$('cashItems').onclick=()=>cashShop('items');$('cashRecharge').onclick=()=>cashShop('recharge');document.querySelectorAll('[data-cash-product]').forEach(b=>b.onclick=()=>{const out=buyCashProduct(p,b.dataset.cashProduct);if(!out.ok){toast(out.reason);return;}save();cashShop();toast('Compra com cash'+(p.testMode?' de teste':'')+' concluída. Ouro preservado.');});if($('testCashCredit'))$('testCashCredit').onclick=()=>{p.wallet.cash+=100000;save();cashShop('recharge');};}
function rankingPanel(type='power'){let rows=[];try{rows=JSON.parse(localStorage.getItem('elyndra-ranks-06')||'[]');}catch{}rows=rankHeroes(Array.isArray(rows)?rows:[],type);showModal('Quadro de heróis','RANKING LOCAL · PERSONAGENS DESTE NAVEGADOR',`<div class="panelTabs"><button id="rankPower" class="${type==='power'?'selected':''}">Poder total</button><button id="rankPvp" class="${type==='pvp'?'selected':''}">Vitórias PvP</button></div><div class="notice">São registros reais dos personagens salvos neste navegador. O laboratório não participa. Ranking global e validação de vitóriasPvP dependem do servidor multiplayer; abates de monstros e testes solo não contam comoPvP.</div>${type==='pvp'&&!rows.some(p=>p.wins>0)?'<p class="rankEmpty">Nenhuma vitóriaPvP registrada. O combate contra jogadores ainda não está conectado.</p>':''}<div class="rankTable"><div class="rankHead"><span>#</span><span>Personagem</span><span>${type==='power'?'Poder':'Vitórias'}</span></div>${rows.map((p,i)=>`<div class="rankRow ${i<3?'rankTop':''}"><b>${i+1}</b><div><strong>${safe(p.name)}</strong><small>${safe(CLASSES[p.classId]?.name||'Herói')} · Nv${p.level}</small></div><b>${(type==='power'?p.power:p.wins).toLocaleString('pt-BR')}</b></div>`).join('')||'<p>Salve um personagem de campanha para entrar no quadro.</p>'}</div>`);$('rankPower').onclick=()=>rankingPanel('power');$('rankPvp').onclick=()=>rankingPanel('pvp');}
function bossLab(division='CATACLYSM'){if(!CONTENT)return;const p=S.player;showModal('Chefes de Elyndra','EXPERIÊNCIA · MUNDIAIS · CATACLISMOS',`<div class="panelTabs">${[['XP','Experiência'],['WORLD','Mundiais'],['CATACLYSM','Cataclismos']].map(([key,label])=>`<button data-boss-division="${key}" class="${division===key?'selected':''}">${label}</button>`).join('')}</div><div class="notice">Encontros adaptados para este jogo solo. Temporizadores são locais. Cataclismos voltam24h após a vitória, fora do laboratório. Cada encontro tem vida e dano próprios; o laboratório não escala chefes baixos ao equipamento250.</div>${CONTENT.bosses.filter(b=>b.division===division).map(b=>{const left=Math.max(0,(p.bossTimers?.[b.id]||0)-Date.now());return `<div class="atlasRow"><div><b>${safe(b.name)}</b><small>Nv${b.level} · acesso${b.level_min} · poder sugerido${b.pc_recommended?.toLocaleString('pt-BR')||'—'}</small><small>${left&&!p.testMode?'Retorno em '+Math.ceil(left/3600000)+'h':division==='CATACLYSM'?'Núcleos, plumas, essência e fragmentos de extensor':'EXP, ouro e materiais'}</small></div><button data-boss="${b.id}" class="smallbtn">${!p.testMode&&p.level<b.level_min?'🔒 Nv'+b.level_min:left&&!p.testMode?'Aguardando':'Enfrentar'}</button></div>`;}).join('')}`);document.querySelectorAll('[data-boss-division]').forEach(b=>b.onclick=()=>bossLab(b.dataset.bossDivision));document.querySelectorAll('[data-boss]').forEach(b=>b.onclick=()=>{const meta=CONTENT.bosses.find(m=>m.id===b.dataset.boss);if(!p.testMode&&p.level<meta.level_min){toast('Requer nível '+meta.level_min+'.');return;}if(!p.testMode&&(p.bossTimers?.[meta.id]||0)>Date.now()){toast('Este chefe ainda não renasceu.');return;}p.zone='dungeon';p.x=17;p.y=14;S.dgName=meta.name;S.dgData=null;S.bossEncounter=meta;S.decor=decorations('dungeon');S.enemies=[];S.target=null;S.attack=false;S.dungeonWon=false;S.dungeonWave=3;const boss=spawn(22,18,'guardian',meta.level,true);boss.bossMeta=meta;boss.name=meta.name;boss.theme=Math.max(0,CONTENT.regions.findIndex(region=>meta.level>=region.range[0]&&meta.level<=region.range[1]));const factor=meta.division==='CATACLYSM'?4:meta.division==='WORLD'?2:1;boss.hp=boss.maxHp=Math.round(boss.maxHp*factor);boss.atk=Math.round(boss.atk*(meta.division==='CATACLYSM'?1.5:1.15));boss.shield=boss.maxHp*.1;boss.archetype=meta.id.includes('CAT')?'demon':'construct';S.lastCombat=-100;closeModal();r.cam={x:p.x,y:p.y};announce(meta.name);save();});}

$('cashButton').onclick=()=>cashShop();$('rankButton').onclick=()=>rankingPanel();

try{const lab=JSON.parse(localStorage.getItem('elyndra-lab-04')||'null');if(lab?.testMode&&CLASSES[lab.classId]){$('continueLabButton').hidden=false;$('continueLabButton').onclick=()=>start(JSON.parse(localStorage.getItem('elyndra-lab-04')));}}catch{}
